/* A restrained real WebGL depth field, behind the readable projected story. */
(()=>{
 const paper=document.querySelector('.screen-paper'),cv=document.createElement('canvas');cv.className='depth-field';cv.setAttribute('aria-hidden','true');paper.prepend(cv);const gl=cv.getContext('webgl',{alpha:true,antialias:true});if(!gl)return;
 const vertex=`attribute vec2 a;uniform float time;uniform float phase;uniform vec2 pointer;uniform float aspect;varying float fade;void main(){float z=mod(a.y+phase*.28,1.0);float x=a.x+sin(a.y*12.0+time*.12)*.04;float d=.25+z*2.5;vec2 p=vec2(x/aspect,.15-z*.85)/d+pointer*.025;gl_Position=vec4(p,0.,1.);gl_PointSize=1.5+2.5*(1.-z);fade=sin(z*3.14159)*.65;}`;
 const fragment=`precision mediump float;varying float fade;void main(){float r=length(gl_PointCoord-.5);gl_FragColor=vec4(.1,.48,.62,fade*(1.-smoothstep(.15,.5,r)));}`;
 function shader(type,src){const s=gl.createShader(type);gl.shaderSource(s,src);gl.compileShader(s);if(!gl.getShaderParameter(s,gl.COMPILE_STATUS))throw Error('Depth shader compilation failed');return s}
 let program;try{program=gl.createProgram();gl.attachShader(program,shader(gl.VERTEX_SHADER,vertex));gl.attachShader(program,shader(gl.FRAGMENT_SHADER,fragment));gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS))return}catch{return}
 gl.useProgram(program);const points=[];for(let y=0;y<44;y++)for(let x=-22;x<=22;x++)points.push(x/9,y/44);gl.bindBuffer(gl.ARRAY_BUFFER,gl.createBuffer());gl.bufferData(gl.ARRAY_BUFFER,new Float32Array(points),gl.STATIC_DRAW);const loc=gl.getAttribLocation(program,'a');gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);
 const uniforms=Object.fromEntries(['time','phase','pointer','aspect'].map(k=>[k,gl.getUniformLocation(program,k)]));gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);let raf=0;const reduce=matchMedia('(prefers-reduced-motion: reduce)').matches;
 function resize(){const d=Math.min(devicePixelRatio,1.5);cv.width=paper.clientWidth*d;cv.height=paper.clientHeight*d;gl.viewport(0,0,cv.width,cv.height);start()}
 function draw(t){raf=0;const state=window.__storyTimeline;if(!state||state.reading||reduce||document.hidden)return;gl.clear(gl.COLOR_BUFFER_BIT);gl.uniform1f(uniforms.time,t*.001);gl.uniform1f(uniforms.phase,state.position);gl.uniform1f(uniforms.aspect,cv.width/cv.height);gl.uniform2f(uniforms.pointer,state.mx,state.my);gl.drawArrays(gl.POINTS,0,points.length/2);const r=paper.getBoundingClientRect();if(r.bottom>0&&r.top<innerHeight)raf=requestAnimationFrame(draw)}
 function start(){if(!raf)raf=requestAnimationFrame(draw)}addEventListener('resize',resize);addEventListener('scroll',start,{passive:true});document.addEventListener('visibilitychange',start);document.querySelector('#motion-toggle').addEventListener('click',start);resize();
})();
